<template><view class="transfer-page"><NativeStatusSpacer/><view class="topbar"><button @tap="back">‹</button><text>负责人转交</text><view/></view><view class="paper"><view v-if="loading" class="state">正在加载</view><view v-if="error" class="state error"><text>{{error}}</text><button v-if="!authorized&&!loading" @tap="initialize">重试</button></view><view v-if="success" class="success"><text class="name">交接已完成</text><text>新的成长负责人：{{responsibility?.responsibleUser?.name || '姓名未提供'}}</text><button class="primary" @tap="back">返回详情</button></view><template v-else-if="authorized&&child"><view class="profile"><view class="avatar">{{child.studentName.slice(0,1)}}</view><view class="profile-copy"><text class="name">{{child.studentName}}</text><text v-if="child.studentNumber" class="muted">学号 {{child.studentNumber}}</text><text class="muted">当前班级：{{child.classNames || '未分配'}}</text></view></view><view class="form-row"><text class="label">当前负责人</text><view class="person-field"><view class="person-avatar">{{responsibility?.responsibleUser?.name?.slice(0,1)||'·'}}</view><text>{{responsibility?.responsibleUser?.name || '暂未分配'}}</text></view></view><view class="form-row"><text class="label">转交给 <text class="required">*</text></text><picker :range="options.map(person=>person.name)" :disabled="submitting" @change="targetUserId=options[Number($event.detail.value)]?.id||''"><view class="person-field"><text>{{options.find(person=>person.id===targetUserId)?.name || (options.length?'请选择接任人':'暂无可接任人')}}</text><text class="arrow">›</text></view></picker></view><view class="reason-row"><text class="label">转交原因 <text class="required">*</text></text><view class="reason-options"><view v-for="(label,index) in reasonLabels" :key="label" class="reason-option" @tap="chooseReason({detail:{value:String(index)}})"><view class="radio" :class="{checked:reasonIndex===index}"><view v-if="reasonIndex===index"/></view><text>{{label}}</text></view></view></view><view class="note"><text class="label">转交说明</text><textarea v-model="reasonText" :disabled="submitting" maxlength="200" :placeholder="reasonType==='OTHER'?'请说明转交原因（必填）':'请填写转交说明（选填）'"/><text class="count">{{reasonText.length}}/200</text></view><button class="primary" :disabled="submitting||!targetUserId||!options.length" @tap="submit">{{submitting?'正在处理…':'确认转交'}}</button></template></view></view></template>
<script setup lang="ts">
import {ref,computed} from 'vue';
import {onLoad,onShow,onHide,onUnload} from '@dcloudio/uni-app';
import NativeStatusSpacer from '@/components/NativeStatusSpacer.vue';
import {responsibilityApi,type StudentResponsibility,type ResponsiblePerson,type ResponsibilityReason} from '@/api/student-responsibility';
import {institutionDirectoryApi,type DirectoryChild} from '@/api/institution-directory';
import {request} from '@/api/http';
import {getMiniappCapabilities} from '@/api/capability';
import {getOrganizationSession} from '@/session/organization-session';
const child=ref<DirectoryChild|null>(null),responsibility=ref<StudentResponsibility|null>(null),options=ref<ResponsiblePerson[]>([]),targetUserId=ref(''),reasonType=ref<ResponsibilityReason>('WORK_ADJUSTMENT'),reasonText=ref(''),loading=ref(false),submitting=ref(false),error=ref(''),authorized=ref(false),success=ref(false);
const reasons:ResponsibilityReason[]=['WORK_ADJUSTMENT','RESIGNATION_HANDOVER','TEMPORARY_TAKEOVER','OTHER'],reasonLabels=['工作调整','离职交接','临时代管','其他'],reasonIndex=computed(()=>Math.max(0,reasons.indexOf(reasonType.value)));
let studentId='',token='',institutionId='',visible=false,revision=0;
function selection(){return uni.getStorageSync('lingdong.selected-organization') as {accessToken?:string;organizationId?:string;typeCode?:string}|undefined;}
function sameScope(){const s=selection();return !!token&&getOrganizationSession()?.accessToken===token&&s?.accessToken===token&&s.organizationId===institutionId&&['SCHOOL','TRAINING_INSTITUTION'].includes(s.typeCode||'');}
function current(n:number){return visible&&n===revision&&sameScope();}
async function checkAccess(n:number){const [me,cap]=await Promise.all([request<{permissionCodes:string[]}>('/auth/me',{header:{Authorization:`Bearer ${token}`}}),getMiniappCapabilities()]);if(!current(n))return false;if(cap.classManagementEnabled!==true||!['STUDENT_READ','STUDENT_RESPONSIBILITY_READ','STUDENT_RESPONSIBILITY_TRANSFER'].every(p=>me.permissionCodes.includes(p)))throw Error('当前账号没有负责人交接权限或功能未启用');return true;}
async function refresh(n:number){const [now,people]=await Promise.all([responsibilityApi.current(token,studentId,institutionId),responsibilityApi.options(token,studentId,institutionId)]);if(!current(n))return false;responsibility.value=now;options.value=people;return true;}
async function initialize(){visible=true;const n=++revision;token=getOrganizationSession()?.accessToken||'';institutionId=selection()?.organizationId||'';child.value=null;responsibility.value=null;options.value=[];targetUserId.value='';reasonText.value='';reasonType.value='WORK_ADJUSTMENT';authorized.value=false;success.value=false;submitting.value=false;error.value='';loading.value=true;if(!sameScope()||!studentId){error.value='请从当前机构学员详情打开交接';loading.value=false;return;}try{if(!await checkAccess(n))return;const result=await institutionDirectoryApi.detail(token,studentId,institutionId);if(!current(n))return;child.value=result;if(!await refresh(n))return;authorized.value=true;}catch(e){if(current(n))error.value=e instanceof Error?e.message:'加载失败';}finally{if(current(n))loading.value=false;}}
function chooseReason(e:{detail:{value:string}}){if(!submitting.value)reasonType.value=reasons[Number(e.detail.value)]||'WORK_ADJUSTMENT';}
function validReason(){return reasons.includes(reasonType.value)&&reasonText.value.trim().length<=200&&(reasonType.value!=='OTHER'||reasonText.value.trim().length>0);}
async function submit(){if(!current(revision)||!authorized.value||loading.value||submitting.value||success.value)return;if(!targetUserId.value||!validReason()){error.value='请选择接任人，并填写有效的交接原因（其他原因必填，最多200字）';return;}const n=revision,target=targetUserId.value,reason=reasonType.value,text=reasonText.value.trim();submitting.value=true;error.value='';try{if(!await checkAccess(n))return;if(!await refresh(n))return;const person=options.value.find(p=>p.id===target);const version=responsibility.value?.versionNo;if(!person||person.id===responsibility.value?.responsibleUser?.id||typeof version!=='number'||!Number.isInteger(version)||version<0){targetUserId.value='';throw Error('负责人或接任人信息已变化，请重新选择');}let settled=false;uni.showModal({title:'确认交接成长负责人',content:`将${child.value?.studentName||'该学员'}的成长负责人交接给${person.name}，确认继续？`,confirmText:'确认交接',success:result=>{if(!current(n)||settled)return;settled=true;if(!result.confirm){submitting.value=false;return;}void commit(n,{institutionOrganizationId:institutionId,targetUserId:target,reasonType:reason,reasonText:text,expectedVersion:version!});},fail:()=>{if(current(n)){submitting.value=false;error.value='确认未完成，请重试';}}});}catch(e){if(current(n)){submitting.value=false;error.value=e instanceof Error?e.message:'交接准备失败';}}}
async function commit(n:number,data:{institutionOrganizationId:string;targetUserId:string;reasonType:ResponsibilityReason;reasonText:string;expectedVersion:number}){if(!current(n))return;try{const result=await responsibilityApi.transfer(token,studentId,data);if(!current(n))return;responsibility.value=result;success.value=true;targetUserId.value='';}catch(e){if(!current(n))return;const conflict=(e as {statusCode?:number}).statusCode===409;targetUserId.value='';if(conflict){options.value=[];responsibility.value=null;try{await refresh(n);}catch{if(current(n))authorized.value=false;}if(current(n))error.value='负责人信息已变化，已重新加载，请重新选择接任人后确认交接';}else error.value=e instanceof Error?e.message:'交接失败，请重新确认';}finally{if(current(n))submitting.value=false;}}
function hide(){visible=false;++revision;child.value=null;options.value=[];responsibility.value=null;authorized.value=false;submitting.value=false;loading.value=false;error.value='';}
function back(){uni.navigateBack({fail:()=>uni.reLaunch({url:'/pages/institution-student-list/institution-student-list'})});}
onLoad(query=>{studentId=typeof query?.studentId==='string'?query.studentId:'';});onShow(initialize);onHide(hide);onUnload(hide);
</script>
<style scoped>
.transfer-page{min-height:100vh;background:#11634c;color:#273a34}.topbar{height:84rpx;display:flex;align-items:center;justify-content:space-between;padding:0 26rpx;color:white;font-size:31rpx;font-weight:600}.topbar button{margin:0;padding:0;background:transparent;color:white;font-size:48rpx;width:44rpx;line-height:72rpx}.topbar>view{width:44rpx}.paper{min-height:calc(100vh - 130rpx);padding:26rpx 28rpx 36rpx;box-sizing:border-box;border-radius:32rpx 32rpx 0 0;background:linear-gradient(135deg,#fbfdf9,#f6faf7)}.profile{display:flex;gap:22rpx;align-items:center;padding:8rpx 14rpx 30rpx;border-bottom:1rpx solid #e3e9e5}.avatar{width:104rpx;height:104rpx;border-radius:50%;background:#e0eee4;color:#2d6b52;display:flex;align-items:center;justify-content:center;font-size:44rpx}.profile-copy{display:flex;flex-direction:column;gap:5rpx}.name{font-size:31rpx;font-weight:650}.muted{font-size:24rpx;color:#7f8f87;line-height:1.5}.form-row{display:flex;align-items:center;gap:18rpx;padding:20rpx 0;border-bottom:1rpx solid #e4ebe5;font-size:28rpx}.label{font-size:28rpx;flex-shrink:0}.form-row>.label,.reason-row>.label{width:225rpx}.required{color:#c65a49}.person-field{display:flex;align-items:center;gap:14rpx;background:#eef3f1;border:1rpx solid #e1e8e4;border-radius:16rpx;padding:14rpx 18rpx;min-height:44rpx;font-size:27rpx;flex:1}.form-row picker{flex:1;min-width:0}.person-avatar{width:50rpx;height:50rpx;border-radius:50%;background:#d8e7df;display:flex;align-items:center;justify-content:center}.arrow{margin-left:auto;color:#7c9085;font-size:35rpx}.reason-row{display:flex;gap:18rpx;padding:22rpx 0;border-bottom:1rpx solid #e4ebe5}.reason-options{flex:1}.reason-option{display:flex;align-items:center;gap:15rpx;font-size:28rpx;padding:9rpx 0}.radio{width:27rpx;height:27rpx;border-radius:50%;border:2rpx solid #8e9d97;box-sizing:border-box;display:flex;align-items:center;justify-content:center}.radio.checked{border-color:#17775a;background:#17775a}.radio>view{width:11rpx;height:11rpx;border-radius:50%;background:white}.note{padding-top:22rpx;position:relative}.note>.label{display:block;margin-bottom:14rpx}textarea{width:100%;height:144rpx;background:#f6f8f6;border:1rpx solid #e0e7e1;border-radius:18rpx;padding:18rpx 18rpx 32rpx;box-sizing:border-box;font-size:27rpx}.count{position:absolute;right:14rpx;bottom:9rpx;color:#8b9991;font-size:21rpx}.primary{margin:22rpx 0 0;background:linear-gradient(110deg,#196c51,#086041);color:white;font-size:29rpx;border-radius:18rpx;line-height:80rpx}.primary[disabled]{opacity:.45}.state{display:flex;flex-direction:column;gap:14rpx;text-align:center;font-size:26rpx;padding:24rpx;color:#859389}.state button{font-size:25rpx;background:#e7f0e9;color:#23664e}.error{color:#b45f47}.success{display:flex;flex-direction:column;gap:24rpx;text-align:center;padding:50rpx 0}button::after{border:0}
</style>
